from decimal import Decimal
from typing import Any


def _value(source: dict | None, key: str) -> Any:
    if not source:
        return ""
    value = source.get(key, "")
    return "" if value is None else value


def _text(source: dict | None, key: str) -> str:
    value = _value(source, key)
    return "" if value is None else str(value)


def _number(value: Any) -> Decimal:
    if value is None or value == "":
        return Decimal("0")
    if isinstance(value, Decimal):
        return value
    return Decimal(str(value))


def _date_ge(left: str, right: str) -> bool:
    if left == "00000000" or right == "00000000":
        return False
    return left >= right


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    today: str = "20260901",
) -> list[dict]:
    errors: list[dict] = []

    status = _text(record, "STAT_CD")
    amount = _number(_value(record, "AMT"))
    lost_reason = _text(record, "LOST_RSN")
    close_date = _text(record, "CLOSE_DT")
    stage_pct = _number(_value(record, "STAGE_PCT"))

    def add_error(code: str, message: str, severity: str = "BLOCK") -> None:
        errors.append(
            {
                "code": code,
                "message": message,
                "severity": severity,
            }
        )

    # OPP-001
    if not (amount >= Decimal("0")):
        add_error("E3001", "Amount negative")

    # OPP-002
    if not (status == "W" and amount == Decimal("0")):
        pass
    else:
        add_error("E3002", "Won opportunity requires amount")

    # OPP-003
    if not (status == "L" and lost_reason == ""):
        pass
    else:
        add_error("E3003", "Lost reason required")

    # OPP-004
    if not (status == "W" and close_date == "00000000"):
        pass
    else:
        add_error("E3004", "Won opportunity requires close date")

    # OPP-005
    if event == "UPDATE":
        old_status = _text(old, "STAT_CD")
        if old_status == "W" and status != "W":
            add_error("E3005", "Cannot reopen a won opportunity")

    # OPP-006
    stage_consistent = (
        (status == "P" and stage_pct == Decimal("10"))
        or (status == "Q" and stage_pct == Decimal("25"))
        or (status == "N" and stage_pct == Decimal("60"))
        or (status == "W" and stage_pct == Decimal("100"))
        or (status == "L" and stage_pct == Decimal("0"))
    )
    if not stage_consistent:
        add_error("E3006", "Stage percent inconsistent with status")

    # OPP-007
    if event == "INSERT":
        close_date_valid = (
            close_date == "00000000"
            or _date_ge(close_date, today)
        )
        if not close_date_valid:
            add_error("E3007", "Close date in past", "WARN")

    return errors


def is_blocked(errors: list[dict]) -> bool:
    return any(error.get("severity") == "BLOCK" for error in errors)
